        for p in predictor.parameters():
            if p.grad is not None:
                grads.append(p.grad.detach().float().flatten())
        if not grads:
            continue
        g = torch.cat(grads)
        mean_g = g.mean()
        var_g = g.var()
        snr = (mean_g ** 2) / (var_g + 1e-12)
        snr_per_layer[f"layer_{i}"] = snr.item()
